ug":"gimp"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"pricing-model"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Free official desktop application under GNU GPL; no recurring software fee is required. This is free software, not evidence of a paid perpetual license.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"supported-platforms"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Official GNU/Linux, macOS and Windows desktop downloads; check current OS and hardware requirements.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"GIMP supports photo retouching and layered composition. Camera RAW processing uses external plug-ins. CMYK import/export uses RGB storage; a native CMYK editing workflow is not established by this review. PSD fidelity and Photoshop feature parity are not guaranteed.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"no-subscription"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":true,"value_text":null,"value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"pricing-model"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Free official GPL desktop application without a recurring software fee. Optional paid store distributions support development and automatic updates; store terms are separate.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"supported-platforms"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Official Windows, macOS and Linux desktop downloads. Android builds are separate; iPhone and iPad are not supported according to the download page.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Krita specializes in digital painting rather than complete Photoshop image manipulation. Layer compositing, text and filters can differ. Its manual documents PSD loading/saving with supported elements but warns against assuming complete compatibility; review exchanged files.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"no-subscription"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":true,"value_text":null,"value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"pricing-model"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Free Classic desktop release with no recurring software fee. The Microsoft Store release is paid; the official license describes the same functionality except automatic updating. This is proprietary freeware, not open source.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"supported-platforms"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Windows 11, Windows 10 21H2 or newer, or Windows Server 2022; check official 64-bit CPU and Direct3D 11 requirements.","value_number":null,"value_enum":null},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Windows-only desktop editor with layers, drawing, selections, effects and color adjustments. PDN is its native layered format; extra file formats may require plugins. This review does not establish native PSD round-trip or professional print/RAW parity. Check current CPU/GPU requirements.","value_number":null,"value_enum":null}]},{"table":"product_anchors","operation":"upsert","conflictColumns":["product_id","anchor_id","relationship_type"],"rows":[{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","relationship_scope":"desktop-raster-layers-painting-basic-adjustment","scope_description":"Desktop raster layers, painting and basic image adjustment only. GIMP is reviewed for retouching and layered composition; RAW processing uses external plug-ins and native CMYK editing is outside the reviewed scope. No guarantee of full Photoshop, PSD, print-production, automation, AI or team-workflow parity."},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","relationship_scope":"desktop-raster-layers-painting-basic-adjustment","scope_description":"Desktop raster layers, painting and basic image adjustment only. Krita is reviewed primarily for illustration and digital painting, not comprehensive photographic retouching. PSD and text/layer semantics need review. No guarantee of full Photoshop, print-production, automation, AI or team-workflow parity."},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","confidence":0.85,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","relationship_scope":"desktop-raster-layers-painting-basic-adjustment","scope_description":"Desktop raster layers, painting and basic image adjustment only. Paint.NET is reviewed for Windows layers, selections, drawing and color adjustments. PDN is its native layered format; plugin formats do not prove PSD compatibility. No guarantee of full Photoshop, print-production, RAW, automation, AI or team-workflow parity."}]},{"table":"product_problems","operation":"upsert","conflictColumns":["product_id","problem_id"],"rows":[]},{"table":"product_audiences","operation":"upsert","conflictColumns":["product_id","audience_id"],"rows":[]},{"table":"claim_evidence","operation":"upsert","conflictColumns":["seed_key"],"rows":[{"seed_key":"seed-claim:000b9019ae0910a5a992da266ccaa6066520ba683397ad47264753985ec1ae78","evidence_source_id":{"$ref":{"table":"evidence_sources","where":{"seed_key":"escape-draft-0f2b3bdb69d46657"}}},"excerpt":null,"notes":"Seed source reference for [\"gimp\",\"attributes\",\"no-subscription\"]. Source con