rt","conflictColumns":["product_id","problem_id","claim_evidence_id"],"rows":[]},{"table":"product_audience_evidence","operation":"upsert","conflictColumns":["product_id","audience_id","claim_evidence_id"],"rows":[]},{"table":"escape_routes","operation":"upsert","conflictColumns":["slug"],"rows":[]},{"table":"escape_route_products","operation":"upsert","conflictColumns":["escape_route_id","product_id"],"rows":[]}],"evidenceReplacements":[],"routeMembershipReplacements":[],"ownership":{"version":1,"products":["gimp","krita","paint-net"],"routes":[],"sources":[],"taxonomy":{"anchors":[],"attributes":[],"problems":[],"audiences":[]}}}$payload$::jsonb;
