BEGIN
  PERFORM set_config('lock_timeout','10s',true);
  PERFORM pg_advisory_xact_lock(7232003);
  LOCK TABLE software_discovery.evidence_sources,software_discovery.anchors,software_discovery.attributes,software_discovery.problems,software_discovery.audiences,software_discovery.products,software_discovery.product_attributes,software_discovery.product_anchors,software_discovery.product_problems,software_discovery.product_audiences,software_discovery.claim_evidence,software_discovery.product_attribute_evidence,software_discovery.product_anchor_evidence,software_discovery.product_problem_evidence,software_discovery.product_audience_evidence,software_discovery.escape_routes,software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;
  own=data->'ownership';
  IF (SELECT count(*) FROM software_discovery.products WHERE slug IN ('obsidian','things','omnifocus','2do','affine','anytype','appflowy') AND status='published')<>7 THEN RAISE EXCEPTION 'PR5.15 requires accepted PR5.13 published products'; END IF;
  IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='todoist-alternatives-with-a-one-time-purchase' AND status='published' AND editorially_approved) THEN RAISE EXCEPTION 'PR5.15 requires accepted Todoist route'; END IF;
  IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='offline-notion-alternatives' AND status='published' AND editorially_approved) THEN RAISE EXCEPTION 'PR5.15 requires accepted offline route'; END IF;
  FOR op IN SELECT value FROM jsonb_array_elements($pr515_guard$[{"table":"products","keys":["slug"],"before":null,"after":{"slug":"gimp","name":"GIMP","short_description":"A free desktop image editor for photo retouching and composition, with workflow and interchange limits to check before replacing an existing tool.","website_url":"https://www.gimp.org/","status":"draft"}},{"table":"products","keys":["slug"],"before":null,"after":{"slug":"krita","name":"Krita","short_description":"A free digital painting application for illustration and related art workflows, with specific Photoshop interchange differences.","website_url":"https://krita.org/","status":"draft"}},{"table":"products","keys":["slug"],"before":null,"after":{"slug":"paint-net","name":"Paint.NET","short_description":"A Windows image editor with layers, adjustments and effects; the free Classic release and paid Store release use a proprietary license.","website_url":"https://paint.net/","status":"draft"}},{"table":"product_attributes","keys":["product_id","attribute_id"],"before":null,"after":{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"no-subscription"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":true,"value_text":null,"value_number":null,"value_enum":null}},{"table":"product_attributes","keys":["product_id","attribute_id"],"before":null,"after":{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"pricing-model"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Free official desktop application under GNU GPL; no recurring software fee is required. This is free software, not evidence of a paid perpetual license.","value_number":null,"value_enum":null}},{"table":"product_attributes","keys":["product_id","attribute_id"],"before":null,"after":{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"supported-platforms"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Official GNU/Linux, macOS and Windows desktop downloads; check current OS and hardware requirements.","value_number":null,"value_enum":null}},{"table":"product_attributes","keys":["product_id","attribute_id"],"before":null,"after":{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"GIMP supports photo retouching and layered composition. Camera RAW processing uses external plug-ins. CMYK import/export uses RGB storage; a native CMYK editing workflow is not established by this review. PSD fidelity and Photoshop feature parity are not guaranteed.","value_number":null,"value_enum":null}},{"table":"product_attributes","keys":["product_id","attribute_id"],"before":null,"after":{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"no-subscription"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":true,"value_text":null,"value_number":null,"value_enum":null}},{"table":"product_attributes","keys":["product_id","attribute_id"],"before":null,"after":{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"pricing-model"}}},"confidence":0.95,"verification_status":"verified","last_verified_at":"2026-10-12T00:00:00Z","value_boolean":null,"value_text":"Free official GPL desktop application without a recurring software fee. Optional 